//! Default-deny public routing over the generated route manifest.
//!
//! The gateway serves ONLY routes of a validated [`RouteTable`] built from
//! `infra/api-gateway/route-manifest.json` (generated by `scripts/contracts/public_api.py`
//! from the authoritative contracts and the explicit allow-list; CI fails on drift). Every
//! other path is NOT_FOUND before any credential is examined.
//!
//! Construction refuses, so they can never be routed:
//!
//! * upstreams outside [`CUSTOMER_UPSTREAMS`] — Platform Access, Telephony, Privacy
//!   Relay's own process (Contact Vault), the operator console and the gateway itself;
//! * public patterns outside `/v1/` and `/api/v2/`, or naming `internal`, `admin`,
//!   `operator`, `provider-callbacks`, `callbacks` or `metrics`;
//! * upstream paths that are not the public pattern itself, except the Developer
//!   Platform's `/internal/v1/` gateway routes (never an administration namespace);
//! * duplicate ids or (method, pattern) pairs, unknown authentication modes, and
//!   WebSocket routes while `API_GATEWAY_WEBSOCKETS_ENABLED` is off.

use std::{collections::BTreeSet, time::Duration};

use axum::http::Method;
use cf_service_auth::{services, ServiceId};

/// Upstreams that may ever receive customer traffic. Each enforces its own
/// receiver-side authorization (gateway permission + its own resource authorization).
pub const CUSTOMER_UPSTREAMS: &[&str] = &[
    services::DEVELOPER_PLATFORM,
    services::CALLING,
    services::MESSAGING,
    services::NUMBERING,
    services::SMS_GATEWAY,
    services::MEETING_SERVICE,
];

/// Path segments that are never customer-routable.
const FORBIDDEN_SEGMENTS: &[&str] = &[
    "internal",
    "admin",
    "operator",
    "provider-callbacks",
    "callbacks",
    "metrics",
];

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Protocol {
    Rest,
    WebSocket,
}

/// How a request on a route is authenticated.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub enum AuthMode {
    /// A Platform Access API credential, authenticated HERE through Platform Access and
    /// forwarded as a signed delegated context (never as the secret).
    PlatformCredential,
    /// The CF Meet human session of the Developer Console, transported to the Developer
    /// Platform, which verifies it through the Meeting Service session bridge.
    DeveloperSession,
    /// Domain-issued end-user / device tokens the owning service verifies itself; the
    /// gateway only transports them (Part VI §7.6).
    ClientToken,
    RealtimeTicket,
    SignalingCredential,
    MeetingSession,
    ParticipantToken,
    /// No credential (the owning service decides what an anonymous caller may do).
    Anonymous,
}

impl AuthMode {
    pub fn parse(value: &str) -> Option<Self> {
        Some(match value {
            "PLATFORM_CREDENTIAL" => AuthMode::PlatformCredential,
            "DEVELOPER_SESSION" => AuthMode::DeveloperSession,
            "CLIENT_TOKEN" => AuthMode::ClientToken,
            "REALTIME_TICKET" => AuthMode::RealtimeTicket,
            "SIGNALING_CREDENTIAL" => AuthMode::SignalingCredential,
            "MEETING_SESSION" => AuthMode::MeetingSession,
            "PARTICIPANT_TOKEN" => AuthMode::ParticipantToken,
            "ANONYMOUS" => AuthMode::Anonymous,
            _ => return None,
        })
    }

    pub fn as_str(&self) -> &'static str {
        match self {
            AuthMode::PlatformCredential => "PLATFORM_CREDENTIAL",
            AuthMode::DeveloperSession => "DEVELOPER_SESSION",
            AuthMode::ClientToken => "CLIENT_TOKEN",
            AuthMode::RealtimeTicket => "REALTIME_TICKET",
            AuthMode::SignalingCredential => "SIGNALING_CREDENTIAL",
            AuthMode::MeetingSession => "MEETING_SESSION",
            AuthMode::ParticipantToken => "PARTICIPANT_TOKEN",
            AuthMode::Anonymous => "ANONYMOUS",
        }
    }

    /// Modes whose token the owning service verifies (the gateway only transports it).
    pub fn is_passthrough(&self) -> bool {
        !matches!(
            self,
            AuthMode::PlatformCredential | AuthMode::DeveloperSession
        )
    }
}

#[derive(Debug, Clone)]
pub struct RouteDefinition {
    /// Stable catalogue id, e.g. `calling.createCall`.
    pub id: String,
    /// API family (`meetings`, `calling`, `privacy-relay`, `messaging`, `numbering`,
    /// `sms`, `developer-platform`, `gateway`).
    pub domain: String,
    pub method: Method,
    /// Public pattern, e.g. `/v1/calls/{call_id}`.
    pub pattern: String,
    pub protocol: Protocol,
    pub upstream: String,
    /// Upstream path template (same `{param}` names).
    pub upstream_path: String,
    pub auth: Vec<AuthMode>,
    /// Scope the credential must hold (pre-check; the owning service checks again).
    pub required_scope: Option<String>,
    /// Extra client request headers forwarded on this route (lower-case).
    pub forward_headers: Vec<String>,
    /// Per-route deadline (default: the gateway's upstream timeout).
    pub timeout: Option<Duration>,
}

impl RouteDefinition {
    pub fn allows(&self, mode: AuthMode) -> bool {
        self.auth.contains(&mode)
    }
}

#[derive(Debug, Clone, PartialEq, Eq, thiserror::Error)]
pub enum RouteError {
    #[error("route {0}: upstream {1} is not a customer-facing service")]
    ForbiddenUpstream(String, String),
    #[error("route {0}: the public pattern must be a normalized /v1/ or /api/v2/ path without internal, administrative or callback segments")]
    ForbiddenPattern(String),
    #[error("route {0}: the upstream path must be the public pattern (or a Developer Platform /internal/v1/ gateway path) with the pattern's parameters")]
    ForbiddenUpstreamPath(String),
    #[error("route {0} is defined twice")]
    Duplicate(String),
    #[error("route {0}: WebSocket routes require API_GATEWAY_WEBSOCKETS_ENABLED")]
    WebSocketsDisabled(String),
    #[error("route {0}: no or unknown authentication mode")]
    InvalidAuth(String),
}

#[derive(Debug, Clone, PartialEq, Eq)]
enum Segment {
    Literal(String),
    Param(String),
}

const PUBLIC_PREFIXES: &[&str] = &["/v1/", "/api/v2/"];

fn parse_pattern(pattern: &str, prefix: &str) -> Option<Vec<Segment>> {
    let rest = pattern.strip_prefix(prefix)?;
    if rest.is_empty() || rest.ends_with('/') || pattern.len() > 256 {
        return None;
    }
    let mut out = prefix
        .trim_matches('/')
        .split('/')
        .map(|s| Segment::Literal(s.to_string()))
        .collect::<Vec<_>>();
    for s in rest.split('/') {
        let seg = if let Some(name) = s.strip_prefix('{').and_then(|s| s.strip_suffix('}')) {
            (!name.is_empty()
                && name.len() <= 64
                && name.bytes().all(|b| b.is_ascii_alphanumeric() || b == b'_'))
            .then(|| Segment::Param(name.to_string()))
        } else {
            (!s.is_empty()
                && s.bytes()
                    .all(|b| b.is_ascii_lowercase() || b.is_ascii_digit() || b == b'-'))
            .then(|| Segment::Literal(s.to_string()))
        }?;
        out.push(seg);
    }
    Some(out)
}

fn params(segments: &[Segment]) -> BTreeSet<&str> {
    segments
        .iter()
        .filter_map(|s| match s {
            Segment::Param(p) => Some(p.as_str()),
            Segment::Literal(_) => None,
        })
        .collect()
}

/// A matching route: literal-segment count, the route and its bound parameters.
type Candidate<'r, 'p> = (usize, &'r CompiledRoute, Vec<(&'r str, &'p str)>);

#[derive(Debug, Clone)]
struct CompiledRoute {
    definition: RouteDefinition,
    public: Vec<Segment>,
    upstream: Vec<Segment>,
    upstream_service: ServiceId,
}

/// A validated, immutable route table.
#[derive(Debug, Clone, Default)]
pub struct RouteTable {
    routes: Vec<CompiledRoute>,
}

/// A matched route with its bound parameters.
#[derive(Debug, Clone)]
pub struct RouteMatch<'a> {
    pub definition: &'a RouteDefinition,
    pub upstream: &'a ServiceId,
    /// The upstream path with parameters substituted.
    pub upstream_path: String,
}

#[derive(Debug, Clone)]
pub enum Lookup<'a> {
    Matched(RouteMatch<'a>),
    /// The path exists for other methods only.
    MethodNotAllowed(Vec<Method>),
    /// Default deny.
    NoRoute,
}

/// A bound parameter value: unreserved characters and percent-escapes only, never a
/// path separator (encoded or not), never a dot segment, never a NUL.
pub fn valid_param_value(v: &str) -> bool {
    if !(1..=256).contains(&v.len()) || v == "." || v == ".." {
        return false;
    }
    let lower = v.to_ascii_lowercase();
    if ["%2f", "%5c", "%00", "%2e%2e", "%25"]
        .iter()
        .any(|bad| lower.contains(bad))
    {
        return false;
    }
    let b = v.as_bytes();
    let mut i = 0;
    while i < b.len() {
        match b[i] {
            b'%' => {
                if i + 2 >= b.len()
                    || !b[i + 1].is_ascii_hexdigit()
                    || !b[i + 2].is_ascii_hexdigit()
                {
                    return false;
                }
                i += 3;
            }
            c if c.is_ascii_alphanumeric()
                || matches!(c, b'-' | b'_' | b'.' | b'~' | b':' | b'@' | b'+') =>
            {
                i += 1
            }
            _ => return false,
        }
    }
    true
}

impl RouteTable {
    /// The empty table: everything is NOT_FOUND.
    pub fn deny_all() -> Self {
        Self::default()
    }

    pub fn new(definitions: Vec<RouteDefinition>, websockets: bool) -> Result<Self, RouteError> {
        let mut ids = BTreeSet::new();
        let mut keys = BTreeSet::new();
        let mut routes = Vec::new();
        for d in definitions {
            let id = d.id.clone();
            if !CUSTOMER_UPSTREAMS.contains(&d.upstream.as_str()) {
                return Err(RouteError::ForbiddenUpstream(id, d.upstream.clone()));
            }
            if d.auth.is_empty() {
                return Err(RouteError::InvalidAuth(id));
            }
            let public = PUBLIC_PREFIXES
                .iter()
                .find_map(|p| parse_pattern(&d.pattern, p))
                .filter(|segments| {
                    segments.iter().all(|s| match s {
                        Segment::Literal(l) => !FORBIDDEN_SEGMENTS.contains(&l.as_str()),
                        Segment::Param(_) => true,
                    })
                })
                .ok_or_else(|| RouteError::ForbiddenPattern(id.clone()))?;
            let upstream = if d.upstream_path == d.pattern {
                public.clone()
            } else {
                parse_pattern(&d.upstream_path, "/internal/v1/")
                    .filter(|_| d.upstream == services::DEVELOPER_PLATFORM)
                    .filter(|segments| {
                        segments.iter().all(|s| {
                            !matches!(s, Segment::Literal(l) if l == "admin" || l == "operator")
                        })
                    })
                    .ok_or_else(|| RouteError::ForbiddenUpstreamPath(id.clone()))?
            };
            if params(&upstream) != params(&public) {
                return Err(RouteError::ForbiddenUpstreamPath(id));
            }
            if d.protocol == Protocol::WebSocket && !websockets {
                return Err(RouteError::WebSocketsDisabled(id));
            }
            if !ids.insert(id.clone()) || !keys.insert((d.method.to_string(), d.pattern.clone())) {
                return Err(RouteError::Duplicate(id));
            }
            let upstream_service = ServiceId::parse(&d.upstream)
                .map_err(|_| RouteError::ForbiddenUpstream(id.clone(), d.upstream.clone()))?;
            routes.push(CompiledRoute {
                definition: d,
                public,
                upstream,
                upstream_service,
            });
        }
        Ok(Self { routes })
    }

    pub fn len(&self) -> usize {
        self.routes.len()
    }

    pub fn is_empty(&self) -> bool {
        self.routes.is_empty()
    }

    pub fn definitions(&self) -> impl Iterator<Item = &RouteDefinition> {
        self.routes.iter().map(|r| &r.definition)
    }

    /// Whether `path` names a routable public path (any method) — for CORS preflight.
    pub fn path_exists(&self, path: &str) -> Vec<Method> {
        let mut methods = Vec::new();
        if let Lookup::Matched(m) = self.lookup(&Method::OPTIONS, path) {
            methods.push(m.definition.method.clone());
        } else if let Lookup::MethodNotAllowed(ms) = self.lookup(&Method::OPTIONS, path) {
            methods = ms;
        }
        methods
    }

    pub fn lookup(&self, method: &Method, path: &str) -> Lookup<'_> {
        if !PUBLIC_PREFIXES.iter().any(|p| path.starts_with(p)) {
            return Lookup::NoRoute;
        }
        let parts: Vec<&str> = path[1..].split('/').collect();
        let mut other_methods = Vec::new();
        // Literal segments win over parameters (`/calls/history` before `/calls/{id}`).
        let mut best: Option<Candidate<'_, '_>> = None;
        for route in &self.routes {
            if route.public.len() != parts.len() {
                continue;
            }
            let mut bound = Vec::new();
            let mut literals = 0;
            let matched = route.public.iter().zip(&parts).all(|(s, p)| match s {
                Segment::Literal(l) => {
                    literals += 1;
                    l == p
                }
                Segment::Param(name) => {
                    bound.push((name.as_str(), *p));
                    valid_param_value(p)
                }
            });
            if !matched {
                continue;
            }
            if route.definition.method != method {
                other_methods.push(route.definition.method.clone());
                continue;
            }
            if best.as_ref().is_none_or(|(n, _, _)| literals > *n) {
                best = Some((literals, route, bound));
            }
        }
        if let Some((_, route, bound)) = best {
            let upstream_path = std::iter::once(String::new())
                .chain(route.upstream.iter().map(|s| {
                    match s {
                        Segment::Literal(l) => l.clone(),
                        Segment::Param(name) => bound
                            .iter()
                            .find(|(n, _)| n == name)
                            .map(|(_, v)| v.to_string())
                            .unwrap_or_default(),
                    }
                }))
                .collect::<Vec<_>>()
                .join("/");
            return Lookup::Matched(RouteMatch {
                definition: &route.definition,
                upstream: &route.upstream_service,
                upstream_path,
            });
        }
        if other_methods.is_empty() {
            Lookup::NoRoute
        } else {
            other_methods.sort_by(|a, b| a.as_str().cmp(b.as_str()));
            other_methods.dedup();
            Lookup::MethodNotAllowed(other_methods)
        }
    }
}

/// Runtime routing controls (rollback): disabled API families and the owner of the
/// customer webhook routes (Section 53 cut-over).
#[derive(Debug, Clone, Default)]
pub struct RoutingControls {
    pub disabled_domains: BTreeSet<String>,
    /// `true`: `/v1/webhooks*` and `/v1/webhook-deliveries*` go to the Developer
    /// Platform (central webhooks); `false` (default): Calling (legacy owner).
    pub central_webhooks: bool,
}

/// Whether a Calling-contract route is a customer webhook route.
pub fn is_webhook_route(definition: &RouteDefinition) -> bool {
    definition.domain == "calling"
        && (definition.pattern.starts_with("/v1/webhooks")
            || definition.pattern.starts_with("/v1/webhook-deliveries"))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn parameter_values_never_carry_a_path() {
        for ok in [
            "abc",
            "3f0f4c1e-6a7b-4c2d-9e8f-0a1b2c3d4e5f",
            "%F0%9F%91%8D",
            "a.b",
            "cref_1:2",
        ] {
            assert!(valid_param_value(ok), "{ok}");
        }
        for bad in [
            "", ".", "..", "a/b", "%2F", "%2f", "a%5Cb", "%00", "%2E%2E", "%", "%G1", "a b", "a?b",
            "a#b", "%25",
        ] {
            assert!(!valid_param_value(bad), "{bad}");
        }
    }
}
